/**
 * Embed the accepted panel design into the React bundle.
 *
 * `src/ui/design/panel/styles/` is the single source of the shared design (the
 * same CSS Kilo and OpenCode serve). The React panel cannot fetch sibling CSS
 * files, so the two stylesheets are generated into a TypeScript module that
 * `src/ui/web/styles.ts` exports. Run before `tsc`; the generated file is
 * committed so typecheck and tests work without the generator.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const root = fileURLToPath(new URL('../', import.meta.url))
const designDir = `${root}src/ui/design/panel/styles/`
const outfile = `${root}src/ui/web/styles.css.ts`

const css = ['tokens.css', 'app.css']
  .map(file => readFileSync(`${designDir}${file}`, 'utf8'))
  .join('\n')

const banner = `/**
 * Generated by scripts/build-web-styles.mjs from src/ui/design/panel/styles/.
 * Do not edit by hand.
 */
`

writeFileSync(outfile, `${banner}export const PANEL_CSS: string = ${JSON.stringify(css)}\n`)
console.log(`[llm-memory] web styles -> ${outfile} (${(css.length / 1024).toFixed(1)} KiB)`)
